import{z as n,x as d,o as l,c as p,q as E,j as t,D as s,d as r,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"写屏障与 FUA","description":"","frontmatter":{"title":"写屏障与 FUA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/write-barrier-fua.md","filePath":"cs/write-barrier-fua.md","lastUpdated":1791063341000}'),c={name:"cs/write-barrier-fua.md"};function u(f,a,F,B,D,m){const i=d("Mermaid");return l(),p("div",null,[a[2]||(a[2]=E('<h1 id="写屏障与-fua" tabindex="-1">写屏障与 FUA <a class="header-anchor" href="#写屏障与-fua" aria-label="Permalink to &quot;写屏障与 FUA&quot;">​</a></h1><div class="epigraph"><p>屏障要求「之前的写先于之后的写」到达稳定点；FUA 要求这一条请求自己到达介质，而不只是控制器缓存。</p><footer>—— 据 Linux 块层对 flush/FUA 的说明；NVMe 与 SCSI SYNCHRONIZE CACHE / FUA 位；POSIX fsync 的设备侧对应</footer></div><p><a href="/cs/blkio-cgroup">上一课</a>不改变完成含义。<a href="/cs/fsync">fsync</a> 与 <a href="/cs/ext4-journal">日志</a> 最终要变成设备命令。缺口是 <strong>flush 与 FUA</strong>：写缓存、乱序、以及 RAID 写洞为何仍可能发生。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>磁盘有易失写缓存。<code>WRITE</code> 完成可能只到缓存。崩溃则乱序。旧内核用「屏障请求」把队列切开；今日常用：需要时下发 <code>FLUSH</code>（NVMe flush / SCSI sync cache），或给写带 FUA（Force Unit Access）。缺口：FS 何时发（commit 块、日志超块）；合并与调度器不能把 flush 越过；禁用写缓存则 FUA 可变便宜。本课不把每家 SSD 的假完成丑闻写成附录主文，只承认硬件可能谎报。</p><p><span class="marginnote">术语翻译：FUA 就是给某一条写命令加的「必须落到介质、不许只停在控制器缓存」的标记。FLUSH 是把整块缓存统一排空；FUA 是点名某条命令单独走到底，两者还可以组合在同一条请求上。</span></p><p><span class="marginnote">REQ_PREFLUSH 先刷缓存再写；REQ_FUA 这条要到介质。两者可组合。电池后备缓存把它们变成几乎空操作——假设电池真有电。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>JBD2 commit：数据（ordered）先下，再 commit 块带 flush。ZFS uberblock 写同样要求持久顺序。驱动把标志译成 NVMe/SCSI 命令。对照 <a href="/cs/io-polling">轮询</a>：flush 仍是一条命令，只是完成用 poll 收。对照 DAX：没有这条 bio，用 clwb。</p><p><span class="marginnote">直觉类比：写日志像先记在便签（缓存）、再誊进账本（介质）。FLUSH 是「先把便签全部誊清再继续」；FUA 是「这一条必须当场誊进账本」。掉电只丢没誊的便签——只要顺序对了，账本就不会出现「未来的记录」。</span></p>',10)),(l(),t(A,null,{default:s(()=>[o(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22fsync%2Fcommit%22%5D%20--%3E%20FL%5B%22PREFLUSH%22%5D%0A%20%20FL%20--%3E%20W%5B%22%E5%86%99%20commit%20%E5%9D%97%22%5D%0A%20%20W%20--%3E%20FUA%5B%22%E5%8F%AF%E9%80%89%20FUA%22%5D%0A%20%20FUA%20--%3E%20STABLE%5B%22%E7%A8%B3%E5%AE%9A%E5%AD%98%E5%82%A8%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("屏障/FUA 把「块层完成」接到「掉电可恢复」的假设上。没有它们，日志重放可能看见未来的根、过去的叶。不要把标志当成数据库隔离级别。与 "),e("a",{href:"/cs/dm-crypt"},"dm-crypt"),r("：flush 必须穿透映射表传到真正介质。")],-1)),a[5]||(a[5]=e("p",null,"写洞：RAID5 的数据和奇偶即使各自 FUA，若没有条带原子，洞仍在——FUA 不是跨块事务。",-1)),a[6]||(a[6]=e("p",null,"掉电时刻 RAID5 条带怎么裂开的：",-1)),(l(),t(A,null,{default:s(()=>[o(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20W1%5B%22%E5%86%99%E6%95%B0%E6%8D%AE%E5%9D%97%20D%22%5D%20--%3E%20CACHE%5B%22%E9%83%BD%E5%85%88%E8%BF%9B%E6%98%93%E5%A4%B1%E8%AE%BE%E5%A4%87%E7%BC%93%E5%AD%98%22%5D%0A%20%20W2%5B%22%E7%AE%97%E5%B9%B6%E5%86%99%E5%A5%87%E5%81%B6%E5%9D%97%20P%22%5D%20--%3E%20CACHE%0A%20%20PWR%5B%22%E6%AD%A4%E5%88%BB%E6%8E%89%E7%94%B5%22%5D%20--%3E%20LOSE%5B%22%E7%BC%93%E5%AD%98%E9%87%8C%E7%9A%84%E9%83%A8%E5%88%86%E5%86%99%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20LOSE%20--%3E%20HOLE%5B%22D%20%E6%96%B0%20P%20%E6%97%A7%EF%BC%9A%E6%9D%A1%E5%B8%A6%E8%87%AA%E7%9B%B8%E7%9F%9B%E7%9B%BE%22%5D%0A%20%20HOLE%20--%3E%20UNFIX%5B%22FUA%20%E7%AE%A1%E5%8D%95%E5%9D%97%E5%88%B0%E4%BD%8D%EF%BC%8C%E4%B8%8D%E7%AE%A1%E8%B7%A8%E5%9D%97%E5%8E%9F%E5%AD%90%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">常见误区：以为给每条写都加 FUA 就万事大吉。FUA 只保证「这一块」到了介质，不保证「这两块同时」到达——RAID5 的数据与奇偶分别 FUA，掉电时仍可能一新一旧。跨块原子要靠保护信息或日志另管，不在 FUA 的合同里。</span></p><p>实现上：禁用驱动写缓存后 flush 变便宜，但不是所有固件都真关。virtio 的 flush 若宿主忽略，客户 fsync 是空的。文件系统把标志打在 bio 上，映射层必须向下传。 读法上只引用<a href="/cs/blkio-cgroup">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>写屏障与 FUA</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SCSI 保护信息。不保证 virtio 的 flush 在宿主机侧被正确实现——虚拟化后课会再遇。下一课空闲块通知：discard 与 TRIM。</p><p>版本字段会变，课序钉的是机制对象「写屏障与 FUA」，不是某一主线内核的结构体名。 后课默认：持久顺序靠 flush/FUA 传到介质。FS 如何告诉 SSD 哪些块不再有效，下一课 TRIM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>flush 刷控制器缓存；FUA 强制该请求到介质。</li><li>日志提交依赖它们；RAID 写洞仍要另管。</li><li>discard/TRIM 是下一课。</li><li>出处：Linux block；NVMe；SCSI SBC；<em>OSTEP</em> 对 fsync 的设备侧。</li></ul>',9))])}const U=n(c,[["render",u]]);export{S as __pageData,U as default};
